/* Independent in-memory provider for executing the production C policy. */
#ifndef TEST_SERVICE_CORE_PROVIDER_H
#define TEST_SERVICE_CORE_PROVIDER_H
#ifndef FIXTURE_BASE
#define FIXTURE_BASE 0x2000
#endif
#ifndef GB_SERVICE_PROVIDER_ADDRESS
#define GB_SERVICE_PROVIDER_ADDRESS (FIXTURE_BASE + 0x00)
#endif
#define GB_SERVICE_LEASE_ADDRESS (FIXTURE_BASE + 0x0E)
#define GB_SERVICE_LOCK_ADDRESS (FIXTURE_BASE + 0x1A)
#define GB_SERVICE_DIAG_ADDRESS (FIXTURE_BASE + 0x1B)
#define GB_SERVICE_OWNER_ACTIVE_ADDRESS (FIXTURE_BASE + 0x20)
#define GB_SERVICE_OWNER_GEN_ADDRESS (FIXTURE_BASE + 0x28)
#define GB_SERVICE_SCHED_ADDRESS (FIXTURE_BASE + 0x30)
#define GB_SERVICE_OWNER_MAX 8u
extern volatile unsigned char service_memory[65536];
#define GB_SERVICE_PROVIDER_BASE (service_memory + GB_SERVICE_PROVIDER_ADDRESS)
#define GB_SERVICE_LEASE_BASE (service_memory + GB_SERVICE_LEASE_ADDRESS)
#define GB_SERVICE_LOCK service_memory[GB_SERVICE_LOCK_ADDRESS]
#define GB_SERVICE_DIAG service_memory[GB_SERVICE_DIAG_ADDRESS]
#define GB_SERVICE_OWNER_ACTIVE (service_memory + GB_SERVICE_OWNER_ACTIVE_ADDRESS)
#define GB_SERVICE_OWNER_GEN (service_memory + GB_SERVICE_OWNER_GEN_ADDRESS)
#define GB_SERVICE_SCHED_CURRENT service_memory[GB_SERVICE_SCHED_ADDRESS]
#endif
